//! Differential ratchet for the complete `src/engine/keyRepeat.ts` surface.
//! All expected values were generated by executing the canonical TypeScript
//! module; regenerate with `node core-rs/tools/gen-key-repeat-vectors.mjs`.

use factory_core::key_repeat::{
    has_button, read_keys, GbaButton, GbaButtonMask, KeyRepeatCounter, KeyRepeatState,
    GBA_BUTTON_MASK_BITS, INITIAL_KEY_REPEAT_STATE, KEY_REPEAT_CONTINUE_DELAY,
    KEY_REPEAT_START_DELAY,
};
use factory_core::key_repeat_vectors_gen::{
    KEY_REPEAT_BRANCH_CENSUS, KEY_REPEAT_BUTTON_COUNT, KEY_REPEAT_BUTTON_MASK_BITS,
    KEY_REPEAT_CATEGORY_CENSUS, KEY_REPEAT_CONTINUE_DELAY as VECTOR_CONTINUE_DELAY,
    KEY_REPEAT_HAS_BUTTON_CASES, KEY_REPEAT_INITIAL_COUNTER, KEY_REPEAT_INITIAL_HELD_MASK,
    KEY_REPEAT_READ_CASES, KEY_REPEAT_START_DELAY as VECTOR_START_DELAY,
    KEY_REPEAT_VECTOR_CORPUS_SHA256,
};

fn mask(bits: u16) -> GbaButtonMask {
    GbaButtonMask::try_from(bits)
        .unwrap_or_else(|error| panic!("invalid generated mask {bits:#06x}: {error}"))
}

fn counter(value: u8) -> KeyRepeatCounter {
    KeyRepeatCounter::try_from(value)
        .unwrap_or_else(|error| panic!("invalid generated counter {value}: {error}"))
}

#[test]
fn complete_read_keys_results_match_canonically_executed_typescript_vectors() {
    assert_eq!(KEY_REPEAT_READ_CASES.len(), 1580);
    for (index, case) in KEY_REPEAT_READ_CASES.iter().enumerate() {
        let actual = read_keys(
            mask(case.current_mask),
            KeyRepeatState {
                held_keys_raw: mask(case.previous_mask),
                key_repeat_counter: counter(case.previous_counter),
            },
        );
        assert_eq!(
            actual.new_keys.bits(),
            case.expected_new_keys,
            "case {index} {}",
            case.label
        );
        assert_eq!(
            actual.new_and_repeated_keys.bits(),
            case.expected_new_and_repeated_keys,
            "case {index} {}",
            case.label
        );
        assert_eq!(
            actual.next.held_keys_raw.bits(),
            case.expected_next_held_keys,
            "case {index} {}",
            case.label
        );
        assert_eq!(
            actual.next.key_repeat_counter.get(),
            case.expected_next_counter,
            "case {index} {}",
            case.label
        );
    }
}

#[test]
fn initial_state_and_has_button_surface_match_canonically_executed_typescript_vectors() {
    assert_eq!(
        INITIAL_KEY_REPEAT_STATE.held_keys_raw.bits(),
        KEY_REPEAT_INITIAL_HELD_MASK
    );
    assert_eq!(
        INITIAL_KEY_REPEAT_STATE.key_repeat_counter.get(),
        KEY_REPEAT_INITIAL_COUNTER
    );
    assert_eq!(KEY_REPEAT_HAS_BUTTON_CASES.len(), 20);
    for (index, case) in KEY_REPEAT_HAS_BUTTON_CASES.iter().enumerate() {
        let button = GbaButton::try_from(case.button_index)
            .unwrap_or_else(|error| panic!("case {index} {}: {error}", case.label));
        assert_eq!(
            has_button(mask(case.keys_mask), button),
            case.expected,
            "case {index} {}",
            case.label
        );
    }
}

#[test]
fn bounded_domains_category_branch_census_and_corpus_hash_are_ratchet_pinned() {
    assert_eq!(KEY_REPEAT_BUTTON_COUNT, 10);
    assert_eq!(KEY_REPEAT_BUTTON_MASK_BITS, 0x03ff);
    assert_eq!(GBA_BUTTON_MASK_BITS, KEY_REPEAT_BUTTON_MASK_BITS);
    assert_eq!(KEY_REPEAT_START_DELAY, 40);
    assert_eq!(KEY_REPEAT_CONTINUE_DELAY, 5);
    assert_eq!(VECTOR_START_DELAY, KEY_REPEAT_START_DELAY);
    assert_eq!(VECTOR_CONTINUE_DELAY, KEY_REPEAT_CONTINUE_DELAY);
    assert!(GbaButtonMask::try_from(0x0400).is_err());
    assert!(KeyRepeatCounter::try_from(0).is_err());
    assert!(KeyRepeatCounter::try_from(41).is_err());

    assert_eq!(
        KEY_REPEAT_CATEGORY_CENSUS,
        [
            ("all-buttons", 1),
            ("all-current-combinations", 1024),
            ("combination-add-remove-change", 3),
            ("empty", 1),
            ("has-button-absent", 10),
            ("has-button-present", 10),
            ("release", 1),
            ("singleton-through-two-continue-repeats", 510),
            ("unchanged-every-counter", 40),
        ]
    );
    assert_eq!(
        KEY_REPEAT_BRANCH_CENSUS,
        [
            ("joy-new-empty", 544),
            ("joy-new-nonempty", 1036),
            ("joy-repeat-full-held", 31),
            ("shared-counter-decrement", 509),
            ("shared-counter-repeat", 31),
            ("shared-counter-reset", 1040),
        ]
    );
    assert_eq!(
        KEY_REPEAT_VECTOR_CORPUS_SHA256,
        "f67e38c085fdbb74fc600b9ef7622197295e1919020148bcc3356ce00ebf7482"
    );
}
